 WHERE NOT EXISTS (SELECT 1 FROM essentials.geofence_boundaries b
                    WHERE b.geo_id = 'ocd-division/country:us/state:ca/place:monterey_park/ward:5' AND b.mtfcc = 'X0001');

-- Repoint the five district rows off the place geo_id and onto their own polygons.
UPDATE essentials.districts d
   SET geo_id = 'ocd-division/country:us/state:ca/place:monterey_park/ward:' || substring(d.label from '([0-9]+)$')
 WHERE d.ocd_id = 'ocd-division/country:us/state:ca/place:monterey_park'
   AND d.district_type = 'LOCAL'
   AND d.label LIKE 'District %'
   AND d.geo_id = '0648914';

DO $$
DECLARE
  n_geofence   int;
  n_districts  int;
  n_unmatched  int;
  city_area    double precision;
  union_area   double precision;
  uncovered    double precision;
  n_overlap    int;
  n_wrong      int;
BEGIN
  SELECT count(*) INTO n_geofence
    FROM essentials.geofence_boundaries
   WHERE geo_id LIKE 'ocd-division/country:us/state:ca/place:monterey_park/ward:%' AND mtfcc = 'X0001';
  IF n_geofence <> 5 THEN
    RAISE EXCEPTION 'expected 5 Monterey Park ward polygons, got %', n_geofence;
  END IF;

  SELECT count(*) INTO n_districts
    FROM essentials.districts
   WHERE ocd_id = 'ocd-division/country:us/state:ca/place:monterey_park' AND district_type = 'LOCAL' AND label LIKE 'District %';
  IF n_districts <> 5 THEN
    RAISE EXCEPTION 'expected 5 Monterey Park district rows, got %', n_districts;
  END IF;

  -- Every district row must now point at a polygon that exists.
  SELECT count(*) INTO n_unmatched
    FROM essentials.districts d
   WHERE d.ocd_id = 'ocd-division/country:us/state:ca/place:monterey_park' AND d.district_type = 'LOCAL' AND d.label LIKE 'District %'
     AND NOT EXISTS (SELECT 1 FROM essentials.geofence_boundaries b
                      WHERE b.geo_id = d.geo_id AND b.mtfcc = 'X0001');
  IF n_unmatched <> 0 THEN
    RAISE EXCEPTION '% district row(s) point at a geo_id with no polygon', n_unmatched;
  END IF;

  -- COVERAGE, with a tolerance: two digitisations of one city are never equal.
  SELECT public.ST_Area(geometry::geography) INTO city_area
    FROM essentials.geofence_boundaries WHERE geo_id = '0648914';
  SELECT public.ST_Area(public.ST_Union(geometry)::geography) INTO union_area
    FROM essentials.geofence_boundaries
   WHERE geo_id LIKE 'ocd-division/country:us/state:ca/place:monterey_park/ward:%' AND mtfcc = 'X0001';
  uncovered := abs(city_area - union_area) / city_area;
  IF uncovered > 0.02 THEN
    RAISE EXCEPTION 'district union differs from the city polygon by % percent of its area',
                    round((uncovered * 100)::numeric, 2);
  END IF;

  -- The districts must partition the city, not overlap it.
  SELECT count(*) INTO n_overlap
    FROM essentials.geofence_boundaries a
    JOIN essentials.geofence_boundaries b
      ON a.geo_id < b.geo_id
     AND a.geo_id LIKE 'ocd-division/country:us/state:ca/place:monterey_park/ward:%' AND b.geo_id LIKE 'ocd-division/country:us/state:ca/place:monterey_park/ward:%'
     AND a.mtfcc = 'X0001' AND b.mtfcc = 'X0001'
   WHERE public.ST_Area(public.ST_Intersection(a.geometry, b.geometry)::geography) > 1000;
  IF n_overlap <> 0 THEN
    RAISE EXCEPTION '% pair(s) of Monterey Park districts overlap by more than 1000 m2', n_overlap;
  END IF;

  -- END TO END: a point inside each district must return that district's council member,
  -- and only that one. This is the only detector that proves an address reaches a person.
  SELECT count(*) INTO n_wrong
    FROM (VALUES ('ward:1', 'Thomas Wong'), ('ward:2', 'Elizabeth Yang'),
                 ('ward:3', 'Jose Sanchez'), ('ward:4', 'Henry Lo'),
                 ('ward:5', 'Vinh Ngo')) AS want(w, who)
    JOIN essentials.geofence_boundaries b
      ON b.geo_id = 'ocd-division/country:us/state:ca/place:monterey_park/' || want.w AND b.mtfcc = 'X0001'
    LEFT JOIN LATERAL (
      SELECT string_agg(p.full_name, ', ' ORDER BY p.full_name) AS got
        FROM essentials.geofence_boundaries gb
        JOIN essentials.districts d ON d.geo_id = gb.geo_id
        JOIN essentials.offices o ON o.district_id = d.id
        JOIN essentials.office_current_holder och ON och.office_id = o.id
        JOIN essentials.politicians p ON p.id = och.politician_id
       WHERE gb.geo_id LIKE 'ocd-division/country:us/state:ca/place:monterey_park/ward:%' AND gb.mtfcc = 'X0001'
         AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(b.geometry))
    ) hit ON true
   WHERE hit.got IS DISTINCT FROM want.who;
  IF n_wrong <> 0 THEN
    RAISE EXCEPTION '% Monterey Park district(s) do not return exactly their own member for an interior point', n_wrong;
  END IF;

  RAISE NOTICE 'OK: 5 Monterey Park council districts have real geometry and each returns its own member';
END $$;

COMMIT;
